export function bossHudStyle(id){const m=BOSS_HUD_META.units[id];if(!m)return '';const sheet=BOSS_HUD_META.sheets[m.sheet],[x,y,w,h]=m.rect,[px,py,d]=m.portrait,[hx,hy,hw,hh]=m.hpRect,[nx,ny,nw,nh]=m.nameRect;return `--boss-shell:url('assets/boss-hud/${m.file}');--boss-shell-size:${sheet.size[0]/w*100}% ${sheet.size[1]/h*100}%;--boss-shell-position:${x/Math.max(1,sheet.size[0]-w)*100}% ${y/Math.max(1,sheet.size[1]-h)*100}%;--boss-aspect:${w}/${h};--boss-face-x:${(px-d/2)/w*100}%;--boss-face-y:${(py-d/2)/h*100}%;--boss-face-width:${d/w*100}%;--boss-name-x:${nx/w*100}%;--boss-name-y:${ny/h*100}%;--boss-name-width:${nw/w*100}%;--boss-hp-x:${hx/w*100}%;--boss-hp-y:${hy/h*100}%;--boss-hp-width:${hw/w*100}%;--boss-hp-height:${hh/h*100}%;--boss-life-right:${(1-(hx+hw)/w)*100}%;`;}
export async function preloadBossHud(id){const m=BOSS_HUD_META.units[id];if(!m)return;const image=new Image();image.src='assets/boss-hud/'+m.file;await image.decode();}
